const data = $json;
const warnings = [];
const errors   = [];

// Validation souple — ne jamais bloquer le pipeline, avertir seulement

// 1. Champs obligatoires
const required = ["agent", "stage", "artifacts"];
for (const field of required) {
  if (!data[field]) {
    warnings.push('Champ manquant : ' + field);
  }
}

// 2. Files — warning seulement si manquants ou insuffisants
if (!Array.isArray(data.files) || data.files.filter(function(f){ return f && f.path && f.content; }).length < 3) {
  warnings.push('Files insuffisants (' + (data.files?.length ?? 0) + ') — architecture.md, api_spec.json, data_model.md attendus');
  // Compléter avec des fichiers minimaux pour ne pas bloquer la suite
  if (!Array.isArray(data.files)) data.files = [];
  const hasMd  = data.files.some(function(f){ return f && f.path === 'architecture.md'; });
  const hasApi = data.files.some(function(f){ return f && f.path === 'api_spec.json'; });
  const hasDm  = data.files.some(function(f){ return f && f.path === 'data_model.md'; });
  if (!hasMd)  data.files.push({ path: 'architecture.md', content: '# Architecture\n' + (data.summary || '') });
  if (!hasApi) data.files.push({ path: 'api_spec.json',   content: JSON.stringify({ endpoints: data.artifacts?.priority_endpoints || [] }) });
  if (!hasDm)  data.files.push({ path: 'data_model.md',   content: '# Modèle de données\n' + JSON.stringify(data.artifacts?.data_model || {}) });
}

// 3. Artifacts — compléter les champs manquants avec des valeurs par défaut
if (data.artifacts) {
  data.artifacts.stack        = data.artifacts.stack        || 'Node.js / Express';
  data.artifacts.architecture = data.artifacts.architecture || 'MVC';
  data.artifacts.auth         = data.artifacts.auth         || 'none';
  data.artifacts.database     = data.artifacts.database     || 'none';
  data.artifacts.file_manifest = data.artifacts.file_manifest || ['server.js', 'package.json', '.env.example', 'frontend/index.html', 'frontend/style.css', 'frontend/app.js'];
} else {
  warnings.push('Artifacts manquants — structure minimale créée');
  data.artifacts = { stack: 'Node.js / Express', architecture: 'MVC', auth: 'none', database: 'none', priority_endpoints: [], data_model: {}, stores: {}, file_manifest: [] };
}

// 4. Validation des enrichissements LLM (non bloquante)
const enrichmentWarnings = [];
if (data.artifacts) {
  if (data.artifacts.mvp_scope && typeof data.artifacts.mvp_scope !== 'string') {
    data.artifacts.mvp_scope = String(data.artifacts.mvp_scope || '').substring(0, 300);
    enrichmentWarnings.push('mvp_scope converti en string');
  }
  if (data.artifacts.deferred && !Array.isArray(data.artifacts.deferred)) {
    data.artifacts.deferred = [];
    enrichmentWarnings.push('deferred invalide — réinitialisé à []');
  }
  if (data.artifacts.abuse_cases && !Array.isArray(data.artifacts.abuse_cases)) {
    data.artifacts.abuse_cases = [];
    enrichmentWarnings.push('abuse_cases invalide — réinitialisé à []');
  }
  if (data.artifacts.priority_endpoints && !Array.isArray(data.artifacts.priority_endpoints)) {
    data.artifacts.priority_endpoints = [];
    enrichmentWarnings.push('priority_endpoints invalide — réinitialisé à []');
  }
}

return [{
  json: {
    ...data,
    warnings: [...(data.warnings ?? []), ...warnings, ...enrichmentWarnings],
    errors:   [...(data.errors   ?? []), ...errors],
    _validated: true,
    _validated_at: new Date().toISOString()
  }
}];

// ── SÉCURITÉ : Anti-Prompt Injection + Limite taille ──────────────────────
function sanitizeInput(text) {
  if (!text || typeof text !== 'string') return text;

  // Limite taille : 50 000 chars max (environ 12 500 tokens)
  if (text.length > 50000) {
    text = text.substring(0, 50000) + '\n[TRONQUÉ — limite 50K chars atteinte]';
  }

  // Anti-prompt injection : neutraliser les tentatives d'override
  const injectionPatterns = [
    /ignore\s+(all\s+)?previous\s+instructions?/gi,
    /ignore\s+(toutes?\s+)?les?\s+instructions?\s+précédentes?/gi,
    /you\s+are\s+now\s+a/gi,
    /tu\s+es\s+maintenant/gi,
    /\[SYSTEM\]/gi,
    /\[INST\]/gi,
    /<\|system\|>/gi,
    /\[\[reset\]\]/gi,
  ];

  for (const pattern of injectionPatterns) {
    text = text.replace(pattern, '[FILTRÉ]');
  }

  return text;
}

const raw = $input.first().json;
let body;
if (raw.body && typeof raw.body === 'object') {
  body = raw.body;
} else if (typeof raw.body === 'string') {
  try {
    body = JSON.parse(raw.body.replace(/^=+/, '').trim());
  } catch(e) {
    // Corps non JSON valide — utiliser l'objet raw directement
    body = raw;
  }
} else {
  body = raw;
}

if (!body.task_id || !body.userRequest) {
  return [{
    json: {
      error: true,
      error_message: "task_id et userRequest requis",
      timestamp: new Date().toISOString()
    }
  }];
}

return [{ json: { task_id: String(body.task_id), userRequest: sanitizeInput(String(body.userRequest)), environment: String(body.environment || 'staging'), language: String(body.language || 'javascript'), framework: String(body.framework || 'express'), improve_mode: body.improve_mode || false, project_name: body.project_name || '', existing_version: body.existing_version || null, next_version: body.next_version || null, existing_routes: body.existing_routes || [], existing_stores: body.existing_stores || {}, changelog_context: sanitizeInput(body.changelog_context || ''), timestamp: new Date().toISOString() } }];

return [{
  json: {
    model: "codestral-latest",
    messages: [
      { role: "system", content: "Tu es un architecte logiciel expert. Retourne UNIQUEMENT un JSON valide." },
      { role: "user",   content: $json.prompt }
    ],
    temperature: 0,
    max_tokens: 5000,
    response_format: { type: "json_object" }
  }
}];

return [{
  json: {
    agent:     $json.agent,
    stage:     $json.stage,
    summary:   $json.summary,
    files:     $json.files,
    artifacts: {
      ...($json.artifacts || {}),
      // Garantir que stores est toujours présent
      stores: $json.artifacts?.stores || $json.stores || {}
    },
    warnings:  $json.warnings || [],
    errors:    $json.errors   || [],
    task_id:   $json.task_id  || "unknown"
  }
}];

// Parse & Validate LLM Output — sécurisé contre les hallucinations

// ── Plafonnement par ressource (et non par endpoint brut) ────────────────────
// Garantit qu'aucune ressource n'est coupée en cours de route (ex: POST gardé,
// GET perdu). Regroupe les endpoints par ressource dans leur ordre d'apparition,
// conserve les MAX_RESOURCES premières ressources rencontrées avec TOUS leurs
// endpoints, et supprime intégralement les ressources au-delà.
const MAX_RESOURCES = 6;
function capEndpointsByResource(endpoints, maxResources) {
  const health = endpoints.filter(function(ep) { return ep.path === '/health'; });
  const rest = endpoints.filter(function(ep) { return ep.path !== '/health'; });
  const resourceOrder = [];
  rest.forEach(function(ep) {
    const seg = ep.path.replace(/^\//, '').split('/')[0];
    if (seg && resourceOrder.indexOf(seg) === -1) resourceOrder.push(seg);
  });
  const keptResources = resourceOrder.slice(0, maxResources);
  const kept = rest.filter(function(ep) {
    const seg = ep.path.replace(/^\//, '').split('/')[0];
    return keptResources.indexOf(seg) !== -1;
  });
  return health.concat(kept);
}

let task_id = 'unknown';
try {
  task_id = $('Validation & normalisation de l’input').first().json.task_id || 'unknown';
} catch(e) {}

// ── 1. Parser la réponse Mistral ─────────────────────────────────────────────
let data = null;
let parseError = null;

try {
  if ($json.choices?.[0]?.message?.content) {
    const content = $json.choices[0].message.content;
    const raw = typeof content === 'string' ? content : JSON.stringify(content);
    // Nettoyer les backticks markdown que le LLM injecte parfois
    const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    data = JSON.parse(cleaned);
  } else if ($json.agent) {
    // Déjà parsé (chemin déterministe)
    data = $json;
  } else {
    parseError = 'Format de réponse LLM inconnu — ni choices ni agent';
  }
} catch(e) {
  parseError = 'JSON.parse échoué : ' + e.message + ' (réponse tronquée ou invalide)';
}

// ── 2. Fallback si parsing échoue ────────────────────────────────────────
if (!data || parseError) {
  return [{ json: {
    agent: 'architect', stage: 'architecture', task_id,
    summary: 'Erreur parsing LLM : ' + (parseError || 'données nulles'),
    files: [
      { path: 'architecture.md', content: '# Architecture\n\nErreur génération LLM.' },
      { path: 'api_spec.json',   content: JSON.stringify({ endpoints: [] }) },
      { path: 'data_model.md',   content: '{}' }
    ],
    artifacts: { stack: 'Node.js / Express', architecture: 'MVC', auth: 'none',
      database: 'none', priority_endpoints: [], data_model: {}, stores: {},
      mvp_scope: '', deferred: [], abuse_cases: [], project_name: '',
      file_manifest: ['server.js','package.json','.env.example','frontend/index.html','frontend/style.css','frontend/app.js']
    },
    warnings: [parseError || 'Parsing échoué'],
    errors:   [parseError || 'Parsing échoué']
  }}];
}

// ── 3. Validation champ 'agent' ───────────────────────────────────────────
if (!data.agent) data.agent = 'architect';

// ── 4. Sanitiser les fichiers générés ────────────────────────────────────
if (data.files && Array.isArray(data.files)) {
  data.files = data.files.filter(function(f) {
    return f && typeof f.path === 'string' && typeof f.content === 'string' &&
           f.path.trim().length > 0 && f.content.trim().length > 0;
  }).slice(0, 10);  // Max 10 fichiers
}

// ── 5. Sanitiser les artifacts ─────────────────────────────────────────────
if (data.artifacts) {
  const a = data.artifacts;

  // project_name : string courte (max 50 chars, pas de caractères spéciaux dangereux)
  a.project_name = (typeof a.project_name === 'string' && a.project_name.length > 0)
    ? a.project_name.replace(/[<>"'&;]/g, '').substring(0, 50).trim()
    : '';

  // mvp_scope : string (max 300 chars)
  a.mvp_scope = (typeof a.mvp_scope === 'string')
    ? a.mvp_scope.substring(0, 300)
    : (typeof a.mvp_scope === 'object' ? JSON.stringify(a.mvp_scope).substring(0, 200) : '');

  // priority_endpoints : tableau d'objets {method, path, description}
  if (!Array.isArray(a.priority_endpoints)) {
    a.priority_endpoints = [];
  } else {
    a.priority_endpoints = a.priority_endpoints
      .filter(function(ep) {
        return ep && typeof ep.method === 'string' && typeof ep.path === 'string' &&
               ['GET','POST','PUT','PATCH','DELETE'].includes(ep.method.toUpperCase()) &&
               ep.path.startsWith('/');
      })
      .map(function(ep) {
        return { method: ep.method.toUpperCase(), path: ep.path.substring(0,100),
                 description: typeof ep.description === 'string' ? ep.description.substring(0,200) : '' };
      });
    a.priority_endpoints = capEndpointsByResource(a.priority_endpoints, MAX_RESOURCES);  // Max 6 ressources, POST+GET jamais séparés
  }

  // data_model : objet dont les valeurs sont des objets de {field: type}
  if (typeof a.data_model !== 'object' || Array.isArray(a.data_model) || a.data_model === null) {
    a.data_model = {};
  } else {
    Object.keys(a.data_model).forEach(function(res) {
      const model = a.data_model[res];
      if (typeof model !== 'object' || model === null) {
        a.data_model[res] = {};
      } else {
        // Vérifier que les valeurs sont bien 'string' ou 'number'
        Object.keys(model).forEach(function(field) {
          if (!['string','number','boolean'].includes(model[field])) {
            a.data_model[res][field] = 'string';  // forcer string si type invalide
          }
        });
      }
    });
  }

  // stores : objet dont les valeurs ont store_name et required_fields[]
  if (typeof a.stores !== 'object' || Array.isArray(a.stores) || a.stores === null) {
    a.stores = {};
  } else {
    Object.keys(a.stores).forEach(function(res) {
      const s = a.stores[res];
      if (!s || typeof s !== 'object') {
        a.stores[res] = { store_name: res + 's', required_fields: [] };
      } else {
        s.store_name     = typeof s.store_name === 'string' ? s.store_name : res + 's';
        s.required_fields = Array.isArray(s.required_fields)
          ? s.required_fields.filter(function(f){ return typeof f === 'string'; }).slice(0, 15)
          : [];
      }
    });
  }

  // deferred : tableau de strings
  a.deferred = Array.isArray(a.deferred)
    ? a.deferred
        .map(function(d) { return typeof d === 'string' ? d : (typeof d === 'object' && d.feature ? d.feature : JSON.stringify(d)); })
        .filter(function(d) { return d.length > 0; })
        .slice(0, 10)
    : [];

  // abuse_cases : tableau de strings
  a.abuse_cases = Array.isArray(a.abuse_cases)
    ? a.abuse_cases
        .map(function(ac) { return typeof ac === 'string' ? ac : (typeof ac === 'object' && ac.name ? ac.name : JSON.stringify(ac)); })
        .filter(function(ac) { return ac.length > 0; })
        .slice(0, 8)
    : [];

  // Champs requis avec defaults
  a.stack        = typeof a.stack === 'string'        ? a.stack        : 'Node.js / Express';
  a.architecture = typeof a.architecture === 'string' ? a.architecture : 'MVC';
  a.auth         = typeof a.auth === 'string'         ? a.auth         : 'none';
  a.database     = typeof a.database === 'string'     ? a.database     : 'none';
  a.file_manifest = Array.isArray(a.file_manifest)    ? a.file_manifest
    : ['server.js','package.json','.env.example','frontend/index.html','frontend/style.css','frontend/app.js'];
}

return [{ json: { ...data, task_id } }];

return [{
  json: {
    agent:     $json.agent,
    stage:     $json.stage,
    summary:   $json.summary,
    files:     $json.files,
    artifacts: {
      ...($json.artifacts || {}),
      // Garantir que stores est toujours présent
      stores: $json.artifacts?.stores || $json.stores || {}
    },
    warnings:  $json.warnings || [],
    errors:    $json.errors   || [],
    task_id:   $json.task_id  || "unknown"
  }
}];

// Fallback Architect : Mistral indisponible

// ── Plafonnement par ressource (identique à Parse & Validate LLM Output) ─────
const MAX_RESOURCES = 6;
function capEndpointsByResource(endpoints, maxResources) {
  const health = endpoints.filter(function(ep) { return ep.path === '/health'; });
  const rest = endpoints.filter(function(ep) { return ep.path !== '/health'; });
  const resourceOrder = [];
  rest.forEach(function(ep) {
    const seg = ep.path.replace(/^\//, '').split('/')[0];
    if (seg && resourceOrder.indexOf(seg) === -1) resourceOrder.push(seg);
  });
  const keptResources = resourceOrder.slice(0, maxResources);
  const kept = rest.filter(function(ep) {
    const seg = ep.path.replace(/^\//, '').split('/')[0];
    return keptResources.indexOf(seg) !== -1;
  });
  return health.concat(kept);
}

// Lit structured_context depuis Build Payload (flux direct, fiable)
let sc = '';
let task_id = 'unknown';

try {
  const bp = $('Build Payload').first().json;
  sc      = bp._structured_context || '';
  task_id = bp._task_id            || 'unknown';
} catch(e) {}

// Fallback 2 : depuis Validation & normalisation de l'input
if (!sc) {
  try {
    const vn = $('\u2018Validation & normalisation de l\u2019input\u2019') ||
               $('Validation & normalisation de l\u2019input');
    const vnData = vn ? vn.first().json : {};
    sc      = vnData.structured_context || '';
    task_id = task_id !== 'unknown' ? task_id : (vnData.task_id || 'unknown');
  } catch(e) {}
}

let artifacts = {
  stack: 'Node.js / Express', architecture: 'MVC', auth: 'none', database: 'none',
  priority_endpoints: [], data_model: {}, stores: {}, project_name: 'Application',
  mvp_scope: '', deferred: [],
  file_manifest: ['server.js','package.json','.env.example','frontend/index.html','frontend/style.css','frontend/app.js']
};

if (sc && sc.length > 10) {
  try {
    const norm = JSON.parse(sc);
    const resources = Array.isArray(norm.resources) ? norm.resources : [];
    const routes    = Array.isArray(norm.routes)    ? norm.routes    : [];
    const pn        = norm.project_name             || 'Application';

    const endpoints = [{ method: 'GET', path: '/health', description: 'health check' }];
    routes.filter(r => r.path !== '/health').forEach(r => {
      endpoints.push({ method: r.method, path: r.path, description: r.description || r.path });
    });

    const dataModel = {};
    const stores    = {};
    resources.forEach(res => {
      const resName = res.name || res.name_plural;
      const fields  = Object.assign({ id: 'number', created_at: 'string' }, res.fields || {});
      dataModel[resName] = fields;
      stores[resName] = {
        store_name: res.name_plural || (resName + 's'),
        required_fields: res.required_fields || Object.keys(res.fields || {}).filter(k => !['id','created_at'].includes(k))
      };
    });

    artifacts = {
      stack: 'Node.js / Express', architecture: 'MVC', auth: 'none', database: 'none',
      project_name: pn,
      mvp_scope: 'MVP ' + pn + ' — généré en mode fallback déterministe',
      priority_endpoints: capEndpointsByResource(endpoints, MAX_RESOURCES),
      data_model: dataModel, stores: stores, deferred: [],
      file_manifest: ['server.js','package.json','.env.example','frontend/index.html','frontend/style.css','frontend/app.js']
    };
  } catch(e) { /* sc invalide */ }
}

return [{
  json: {
    agent: 'architect', stage: 'architecture', task_id,
    summary: artifacts.project_name + ' — architecture (fallback déterministe)',
    files: [
      { path: 'architecture.md', content: '# ' + artifacts.project_name + '\n\nFallback déterministe.' },
      { path: 'api_spec.json',   content: JSON.stringify({ endpoints: artifacts.priority_endpoints }) },
      { path: 'data_model.md',   content: JSON.stringify(artifacts.data_model, null, 2) }
    ],
    artifacts,
    warnings: ['Mistral indisponible — artifacts construits depuis spec normalisée'],
    errors:   []
  }
}];

// Build Deterministic Artifacts
// Si structured_context est valide, construire les artifacts SANS appel LLM
// Sinon, passer au chemin LLM normal

// ── Plafonnement par ressource (identique aux autres nœuds du pipeline) ──────
const MAX_RESOURCES = 6;
function capEndpointsByResource(endpoints, maxResources) {
  const health = endpoints.filter(function(ep) { return ep.path === '/health'; });
  const rest = endpoints.filter(function(ep) { return ep.path !== '/health'; });
  const resourceOrder = [];
  rest.forEach(function(ep) {
    const seg = ep.path.replace(/^\//, '').split('/')[0];
    if (seg && resourceOrder.indexOf(seg) === -1) resourceOrder.push(seg);
  });
  const keptResources = resourceOrder.slice(0, maxResources);
  const kept = rest.filter(function(ep) {
    const seg = ep.path.replace(/^\//, '').split('/')[0];
    return keptResources.indexOf(seg) !== -1;
  });
  return health.concat(kept);
}

const inp = $input.first().json;
const sc  = inp.structured_context || '';

if (!sc || sc.length < 20) {
  return [{ json: { ...inp, _use_deterministic: false } }];
}

let norm;
try { norm = JSON.parse(sc); }
catch(e) { return [{ json: { ...inp, _use_deterministic: false } }]; }

const resources = Array.isArray(norm.resources) ? norm.resources : [];
const routes    = Array.isArray(norm.routes)    ? norm.routes    : [];

if (resources.length === 0) {
  return [{ json: { ...inp, _use_deterministic: false } }];
}

const pn = norm.project_name || inp.project_name || 'Application';

// Construire priority_endpoints
const endpoints = [];
endpoints.push({ method: 'GET', path: '/health', description: 'health check — retourne {status, uptime}' });
routes.filter(r => r.path !== '/health').forEach(r => {
  endpoints.push({ method: r.method, path: r.path, description: r.description || (r.method + ' ' + r.path) });
});
const cappedEndpoints = capEndpointsByResource(endpoints, MAX_RESOURCES);

// Construire data_model et stores
const dataModel = {};
const stores    = {};
resources.forEach(res => {
  const resName = res.name;
  const fields  = Object.assign({ id: 'number', created_at: 'string' }, res.fields || {});
  dataModel[resName] = fields;
  stores[resName] = {
    store_name:     res.name_plural || (resName + 's'),
    required_fields: (res.required_fields || []).filter(f => !['id','created_at'].includes(f)),
    shared:         (res.shared === true) || (Array.isArray(norm.shared_resources) && norm.shared_resources.indexOf(res.name_plural || (resName + 's')) >= 0)
  };
});

const artifacts = {
  stack:       'Node.js / Express',
  architecture:'MVC',
  auth:        'none',
  database:    'none',
  project_name: pn,
  mvp_scope:   'MVP ' + pn + ' — génération déterministe depuis spec normalisée',
  priority_endpoints: cappedEndpoints,
  data_model:  dataModel,
  stores:      stores,
  shared_resources: (Array.isArray(norm.shared_resources) ? norm.shared_resources : Object.keys(stores).filter(function(k){ return stores[k].shared; }).map(function(k){ return stores[k].store_name; })),
  deferred:    [],
  file_manifest: ['server.js','package.json','.env.example','frontend/index.html','frontend/style.css','frontend/app.js']
};

return [{
  json: {
    _use_deterministic: true,
    agent:    'architect',
    stage:    'design',
    task_id:  inp.task_id || 'unknown',
    summary:  pn + ' — architecture générée depuis spec normalisée',
    files: [
      { path: 'architecture.md', content: '# ' + pn + '\n\nArchitecture déterministe depuis spec normalisée Forge IA.' },
      { path: 'api_spec.json',   content: JSON.stringify({ endpoints: cappedEndpoints }, null, 2) },
      { path: 'data_model.md',   content: JSON.stringify(dataModel, null, 2) }
    ],
    artifacts,
    warnings: [],
    errors:   []
  }
}];
